@startuml

class Building {
  + m : int
}

class Floor {
}

class Elevator {
}

class Button {
  + isLit : boolean
  + press() : void
  + lightUp() : void
  + turnOff() : void
}

enum Direction {
  UP
  DOWN
}

enum ButtonType {
  UP
  DOWN
  FLOOR_STOP
}

Building "1" *-- "m" Floor
Building "1" *-- "*" Elevator
Elevator "1" *-- "*" Button : has
Floor "1" *-- "0..2" Button : has
Button "*" -- "1" Elevator : targets
Button "*" -- "1" Floor : locatedAt

@enduml

